a = [int(s) for s in open('17.txt') if s.strip()]

mx = max(x for x in a if abs(x) % 10 == 0)         # до цикла

def f(x):
    return 10 <= abs(x) <= 99                       # двузначное

good = []
for x1, x2, x3 in zip(a, a[1:], a[2:]):
    if f(x1) + f(x2) + f(x3) == 2 and x1 + x2 + x3 <= mx:
        good.append(x1 + x2 + x3)
print(len(good), max(good))
